    @Test func wifSeed() throws {
        // The private keys in the tests below are derived from the following master private key:
        // Extended Private Key: tprv8ZgxMBicQKsPd9TeAdPADNnSyH9SSUUbTVeFszDE23Ki6TBB5nCefAdHkK8Fm3qMQR6sHwA56zqRmKmxnHk37JkiFzvncDqoKmPWubu7hDF
        // Seed: cUkG8i1RFfWGWy5ziR11zJ5V4U4W3viSFCfyJmZnvQaUsd1xuF3T

        let seedAsWIFSecretKey = try #require(SecretKey(wif: "cUkG8i1RFfWGWy5ziR11zJ5V4U4W3viSFCfyJmZnvQaUsd1xuF3T"))
        let masterKeyDuplicate = try ExtendedKey(seed: seedAsWIFSecretKey.data, mainnet: false)
        let masterKey = try ExtendedKey(masterKey)
        #expect(masterKey == masterKeyDuplicate)
    }

