        // and spends the following inputs:
        // TXID: 75ddabb27b8845f5247975c8a5ba7c6f336c4570708ebe230caf6db5217ae858, Index: 0
        // TXID: 1dea7cd05979072a3578cab271c02244ea8a090bbb46aa680a65ecd027048d83, Index: 1

        let tx = Transaction(version: .v2, ins: [
            .init(outpoint: .init(tx: .init([0x75, 0xdd, 0xab, 0xb2, 0x7b, 0x88, 0x45, 0xf5, 0x24, 0x79, 0x75, 0xc8, 0xa5, 0xba, 0x7c, 0x6f, 0x33, 0x6c, 0x45, 0x70, 0x70, 0x8e, 0xbe, 0x23, 0x0c, 0xaf, 0x6d, 0xb5, 0x21, 0x7a, 0xe8, 0x58].reversed()), out: 0)),
