        ], outs: [
            .init(value: 149990000, script: try! .init(Data([0x00, 0x14, 0xd8, 0x5c, 0x2b, 0x71, 0xd0, 0x06, 0x0b, 0x09, 0xc9, 0x88, 0x6a, 0xeb, 0x81, 0x5e, 0x50, 0x99, 0x1d, 0xda, 0x12, 0x4d]))),
            .init(value: 100000000, script: try! .init(Data([0x00, 0x14, 0x00, 0xae, 0xa9, 0xa2, 0xe5, 0xf0, 0xf8, 0x76, 0xa5, 0x88, 0xdf, 0x55, 0x46, 0xe8, 0x74, 0x2d, 0x1d, 0x87, 0x00, 0x8f]))),

        ])

        // must create this PSBT:
        // Bytes in Hex: 
        // Base64 String: cHNidP8BAJoCAAAAAljoeiG1ba8MI76OcHBFbDNvfLqlyHV5JPVFiHuyq911AAAAAAD/////g40EJ9DsZQpoqka7CwmK6kQiwHGyyng1Kgd5WdB86h0BAAAAAP////8CcKrwCAAAAAAWABTYXCtx0AYLCcmIauuBXlCZHdoSTQDh9QUAAAAAFgAUAK6pouXw+HaliN9VRuh0LR2HAI8AAAAAAAAAAAA=
        let expectedPSBT = try PartiallySignedTx(psbt0)

        // Create a PSBT
