    @Test func signer() throws {
        // Given the above updated PSBT, a signer that supports SIGHASH_ALL for P2PKH and P2WPKH spends and uses RFC6979 for nonce generation and has the following keys:
        // cP53pDbR5WtAD8dYAW9hhTjuvvTVaEiQBdrz9XPrgLBeRFiyCbQr (m/0'/0'/0')
        // cR6SXDoyfQrcp4piaiHE97Rsgta9mNhGTen9XeonVgwsh4iSgw6d (m/0'/0'/2')

        let secretKey0 = try #require(SecretKey(wif: "cP53pDbR5WtAD8dYAW9hhTjuvvTVaEiQBdrz9XPrgLBeRFiyCbQr"))

        // Additional sanity check (can potentially be omitted)
        let masterKey = try ExtendedKey(masterKey)
        let secretKeyCompare = masterKey.derive(.init(fingerprint: masterKey.fingerprint, indices: [0, 0, 0], harden: [true, true, true]))
        #expect(secretKey0 == secretKeyCompare.secretKey)

        let secretKey1 = try #require(SecretKey(wif: "cR6SXDoyfQrcp4piaiHE97Rsgta9mNhGTen9XeonVgwsh4iSgw6d"))

        // must create this PSBT:
        // Bytes in Hex: 
        // Base64 String: 

        // Sign PSBT
        var psbt = try PartiallySignedTx(psbt2)
        try psbt.sign(input: 0, using: secretKey0)
        try psbt.sign(input: 1, using: secretKey1)
        let expectedPSBT = try PartiallySignedTx(psbt3)
        #expect(psbt == expectedPSBT)
    }

    @Test func signer2() throws {
        // Given the above updated PSBT, a signer with the following keys:
        // cT7J9YpCwY3AVRFSjN6ukeEeWY6mhpbJPxRaDaP5QTdygQRxP9Au (m/0'/0'/1')
        // cNBc3SWUip9PPm1GjRoLEJT6T41iNzCYtD7qro84FMnM5zEqeJsE (m/0'/0'/3')

        let secretKey0 = try #require(SecretKey(wif: "cT7J9YpCwY3AVRFSjN6ukeEeWY6mhpbJPxRaDaP5QTdygQRxP9Au"))

        // Additional sanity check (can potentially be omitted)
        let masterKey = try ExtendedKey(masterKey)
        let secretKeyCompare = masterKey.derive(.init(fingerprint: masterKey.fingerprint, indices: [0, 0, 1], harden: [true, true, true]))
        #expect(secretKey0 == secretKeyCompare.secretKey)

        let secretKey1 = try #require(SecretKey(wif: "cNBc3SWUip9PPm1GjRoLEJT6T41iNzCYtD7qro84FMnM5zEqeJsE"))

        // must create this PSBT:
        // Bytes in Hex: 
        // Base64 String: 

        // Sign PSBT
        var psbt = try PartiallySignedTx(psbt2)
        try psbt.sign(input: 0, using: secretKey0)
        try psbt.sign(input: 1, using: secretKey1)

        let expectedPSBT = try PartiallySignedTx(psbt3_)

        #expect(psbt != expectedPSBT) // Official test vector did not grind for low R signature

        // Let's check each signature instead.
        let sighash = SignatureHash(tx: psbt.unsignedTx, input: 0, sighashType: psbt.ins[0].sighashType!, scriptCode: psbt.ins[0].redeemScript!.data).data

        let signatureA = try #require(psbt.ins[0].partialSigs[secretKey0.pubkey])
        let signatureA_ = try #require(expectedPSBT.ins[0].partialSigs[secretKey0.pubkey])

        #expect(signatureA.sig.verify(hash: sighash, pubkey: secretKey0.pubkey))
        #expect(signatureA_.sig.verify(hash: sighash, pubkey: secretKey0.pubkey))

        let sighashB = SignatureHash.Segwit(tx: psbt.unsignedTx, input: 1, sighashType: psbt.ins[1].sighashType!, scriptCode: psbt.ins[1].witnessScript!.data, prevout: psbt.ins[1].witnessPrevout!).data

        let signatureB = try #require(psbt.ins[1].partialSigs[secretKey1.pubkey])
        let signatureB_ = try #require(expectedPSBT.ins[1].partialSigs[secretKey1.pubkey])

        #expect(signatureB.sig.verify(hash: sighashB, pubkey: secretKey1.pubkey))
        #expect(signatureB_.sig.verify(hash: sighashB, pubkey: secretKey1.pubkey))
    }

    @Test func combiner() throws {
        // Given both of the above PSBTs, a combiner must create this PSBT:
        // Bytes in Hex: 
        // Base64 String: 
        var psbt = try PartiallySignedTx(psbt3)
        let psbtB = try PartiallySignedTx(psbt3_)
        psbt.combine(with: psbtB)
        let expectedPSBT = try PartiallySignedTx(psbt4)
        #expect(psbt == expectedPSBT)
    }

